  4	/**
  5	 * A single folder entry in a VS Code .code-workspace file.
  6	 */
  7	interface WorkspaceFolder {
  8	    path: string;
  9	    name: string;
 10	}
 11	
 12	/**
 13	 * Minimal shape of the VS Code .code-workspace JSON file.
 14	 * We only enforce the `folders` property; all other properties are preserved as-is.
 15	 */
 16	interface VsCodeWorkspaceFile {
 17	    folders: WorkspaceFolder[];
 18	    [key: string]: unknown;
 19	}
 20	
 21	/**
 22	 * Returns the absolute path for a VS Code .code-workspace file.
 23	 *
 24	 * Format: `{projectsFolder}/{projectSlug}/{projectSlug}-{workspaceId}.code-workspace`
 25	 *
 26	 * The file is nested inside the per-project subdirectory so that each
 27	 * project's on-disk footprint (repositories + workspace file) is
 28	 * self-contained under a single directory.
 29	 */
 30	export function getWorkspaceFilePath(
 31	    projectsFolder: string,
 32	    projectSlug: string,
 33	    workspaceId: string,
 34	): string {
 35	    return path.join(projectsFolder, projectSlug, `${projectSlug}-${workspaceId}.code-workspace`);
 36	}
 37	
 38	/**
 39	 * Creates or updates a VS Code .code-workspace file.
 40	 *
 41	 * - If the file does **not** exist, a new file is created with the `folders`
 42	 *   array and an empty `settings` object.
 43	 * - If the file **does** exist, only the `folders` property is replaced;
 44	 *   all other properties (`settings`, `extensions`, custom keys, etc.) are
 45	 *   preserved verbatim.
 46	 *
 47	 * Each folder entry has the form:
 48	 * ```json
 49	 * { "path": "<absolute-path>", "name": "<slug> (<workspaceId>)" }
 50	 * ```
 51	 *
 52	 * @param workspaceId  Workspace identifier used in folder display names.
 53	 * @param repoPaths    Ordered list of repository entries to include as folders.
 54	 * @param filePath     Absolute path where the .code-workspace file is written.
 55	 */
 56	export function generateWorkspaceFile(
 57	    workspaceId: string,
 58	    repoPaths: { slug: string; path: string }[],
 59	    filePath: string,
 60	): void {
 61	    const folders: WorkspaceFolder[] = repoPaths.map((repo) => ({
 62	        path: repo.path,
 63	        name: `${repo.slug} (${workspaceId})`,
 64	    }));
 65	
 66	    let existing: VsCodeWorkspaceFile | null = null;
 67	    if (fs.existsSync(filePath)) {
 68	        try {
 69	            const raw = fs.readFileSync(filePath, 'utf8');
 70	            existing = JSON.parse(raw) as VsCodeWorkspaceFile;
 71	        } catch {
 72	            // Unreadable or invalid JSON — treat as non-existent and recreate.
 73	            existing = null;
 74	        }
 75	    }
 76	
 77	    const output: VsCodeWorkspaceFile =
 78	        existing !== null
 79	            ? { ...existing, folders }
 80	            : { folders, settings: {} };
 81	
 82	    const parentDir = path.dirname(filePath);
 83	    fs.mkdirSync(parentDir, { recursive: true });
 84	
 85	    fs.writeFileSync(filePath, JSON.stringify(output, null, 4) + '\n', 'utf8');
 86	}
