 88	/**
 89	 * Deletes the VS Code workspace file at the given path.
 90	 * Silent no-op if the file does not exist.
 91	 */
 92	export function removeWorkspaceFile(filePath: string): void {
 93	    try {
 94	        fs.rmSync(filePath);
 95	    } catch (err) {
 96	        if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
 97	            return;
 98	        }
 99	        throw err;
100	    }

101	}
