103	/**
104	 * One-time migration utility: moves `.code-workspace` files from the legacy
105	 * flat layout (`{projectsFolder}/{slug}-*.code-workspace`) into the nested
106	 * per-project layout (`{projectsFolder}/{slug}/{slug}-*.code-workspace`).
107	 *
108	 * Behaviour:
109	 * - Only files whose base name starts with a known project slug followed by `-`
110	 *   are considered.  Unrecognized files are left untouched.
111	 * - Files that are already at the correct target location are skipped (the
112	 *   function is idempotent).
113	 * - The target parent directory is created if it does not already exist.
114	 *
115	 * @param projectsFolder  Absolute path to the root folder that contains all
116	 *                        project subdirectories and (legacy) flat workspace files.
117	 * @param projectSlugs    Array of known project slug strings.  Only files
118	 *                        matching one of these slugs are migrated.
119	 * @returns               The number of files that were actually moved.
120	 */
121	export function migrateWorkspaceFiles(
122	    projectsFolder: string,
123	    projectSlugs: string[],
124	): number {
125	    let moved = 0;
126	
127	    // Build a Set for O(1) slug lookups.
128	    const slugSet = new Set(projectSlugs);
129	
130	    let entries: fs.Dirent[];
131	    try {
132	        entries = fs.readdirSync(projectsFolder, { withFileTypes: true });
133	    } catch (err) {
134	        if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
135	            // projectsFolder does not yet exist — nothing to migrate.
136	            return 0;
137	        }
138	        throw err;
139	    }
140	
141	    for (const entry of entries) {
142	        if (!entry.isFile()) continue;
143	
144	        const fileName = entry.name;
145	        if (!fileName.endsWith('.code-workspace')) continue;
146	
147	        // Determine which known slug this file belongs to, if any.
148	        // File names are of the form `{slug}-{workspaceId}.code-workspace`.
149	        // We find the matching slug by checking whether the file name starts
150	        // with `{slug}-`.  If multiple slugs could match (e.g. `foo` and
151	        // `foo-bar`), we pick the longest matching slug (most specific).
152	        let matchedSlug: string | null = null;
153	        for (const slug of slugSet) {
154	            if (fileName.startsWith(`${slug}-`)) {
155	                if (matchedSlug === null || slug.length > matchedSlug.length) {
156	                    matchedSlug = slug;
157	                }
158	            }
159	        }
160	
161	        if (matchedSlug === null) continue; // unrecognized file — leave it alone
162	
163	        const sourcePath = path.join(projectsFolder, fileName);
164	        const targetDir  = path.join(projectsFolder, matchedSlug);
165	        const targetPath = path.join(targetDir, fileName);
166	
167	        // Already at the correct location — idempotency guard.
168	        if (sourcePath === targetPath) continue;
169	
170	        // If the file somehow already exists at the target, skip to avoid
171	        // overwriting (treat as already migrated).
172	        if (fs.existsSync(targetPath)) continue;
173	
174	        fs.mkdirSync(targetDir, { recursive: true });
175	        fs.renameSync(sourcePath, targetPath);
176	        moved++;
177	    }
178	
179	    return moved;
180	}

